
/* script.c - event script virtual machine (blocking). Bytecode is generated by
 * tools/content.py and lives in data banks; bytes are fetched via far_byte(). */
#include <string.h>
#include "hm.h"
#include "gba_dirs.h"

uint16_t script_pending = 0xFFFF;

enum {
    O_END, O_SAY, O_JMP, O_IF, O_SETF, O_CLRF, O_GIVE, O_TAKE, O_EV, O_INFL, O_ALERT,
    O_CHOICE, O_WARP, O_MUSIC, O_SFX, O_WAIT, O_FADEOUT, O_FADEIN, O_SHAKE,
    O_IMAGE, O_IMAGE_END, O_AMOVE, O_PMOVE, O_PFACE, O_SETTILE, O_CHAPTER,
    O_HEAL, O_SAVE, O_ENDING, O_SPECIAL, O_SETVAR, O_ADDVAR, O_AHIDE, O_ASHOW,
    O_NOISE, O_SHADOW, O_AMMO, O_BANDAGE, O_BOTTLE, O_UNLOCK, O_AFACE,
    O_FLASH, O_CALL, O_DAMAGE, O_REDRAW, O_WEAPON, O_CLOSE, O_PHIDE, O_PSHOW,
    O_AWARP, O_CREDITS, O_REDFLASH, O_CHECKPOINT, O_ALERTSET, O_MUSICRESUME
};
enum { C_FLAG, C_ITEM, C_EV, C_INFL, C_VAREQ, C_VARGE, C_ALERT, C_EVCOUNT, C_STAGE,
       C_CHAPTER, C_AMMO, C_NOT, C_MERCY };

extern uint8_t shake_t;
extern void trail_reset(void);
void spawn_obj_actor(uint8_t oi);
uint8_t mercy_count(void);

static uint8_t s_bank;
static const uint8_t *s_base;
static uint16_t pc;
static uint8_t map_music;

static uint8_t rb(void) { return far_byte(s_bank, s_base + pc++); }
static uint16_t rw(void) { uint16_t v = rb(); return v | ((uint16_t)rb() << 8); }

static uint8_t eval_cond(void) {
    uint8_t t = rb(), a, b;
    switch (t) {
    case C_NOT: return !eval_cond();
    case C_FLAG: return flag_get(rw());
    case C_ITEM: return item_has(rb());
    case C_EV: return ev_has(rb());
    case C_INFL: return gs.influence >= rb();
    case C_VAREQ: a = rb(); b = rb(); return gs.vars[a] == b;
    case C_VARGE: a = rb(); b = rb(); return gs.vars[a] >= b;
    case C_ALERT: return alert_level() >= rb();
    case C_EVCOUNT: return ev_count() >= rb();
    case C_STAGE: return infl_stage() >= rb();
    case C_CHAPTER: return gs.chapter >= rb();
    case C_AMMO: return gs.ammo >= rb();
    case C_MERCY: return mercy_count() >= rb();
    }
    return 0;
}

static actor_t *find_actor(uint8_t oi) {
    uint8_t i;
    for (i = 0; i < MAX_ACTORS; i++)
        if (actors[i].type && actors[i].obj == oi) return &actors[i];
    return 0;
}

static void cut_frame(void) {
    wait_frame();
    apply_scroll();
    render_sprites();
}

static const int8_t ddx[4] = {0, 0, -1, 1};
static const int8_t ddy[4] = {1, -1, 0, 0};

static void read_str(char *dst, uint8_t max) {
    uint8_t c, n = 0;
    while ((c = rb()) != 0) if (n < max) dst[n++] = c;
    dst[n] = 0;
}

static void op_choice(void) {
    char a[16], b[16];
    uint16_t alt;
    uint8_t sel;
    read_str(a, 15);
    read_str(b, 15);
    alt = rw();
    sel = dlg_choice2(a, b);
    if (sel) pc = alt;
}

static void save_prompt(void) {
    dlg_say("Rest a moment?\nYour progress can\nbe saved here.\v");
    if (dlg_choice2("SAVE", "NOT NOW") == 0) {
        if (save_write()) {
            sfx_play(18);
            dlg_say("Progress saved.");
        } else {
            dlg_say("SAVE FAILED.\nThe cartridge\nmemory did not\nverify.");
        }
    }
}

static void run_one(uint16_t id) {
    uint8_t op, a, b, c, d;
    uint16_t w;
    actor_t *ac;
    far_t f;
    uint8_t sv_bank = s_bank;
    const uint8_t *sv_base = s_base;
    uint16_t sv_pc = pc;

    f = script_dir_get(id);
    s_bank = f.bank;
    s_base = f.ptr;
    pc = 0;
    for (;;) {
        op = rb();
        switch (op) {
        case O_END:
            goto done;
        case O_SAY: {
            const uint8_t *e = dlg_say_far(s_bank, s_base + pc);
            pc = (uint16_t)(e - s_base);
            break;
        }
        case O_JMP: pc = rw(); break;
        case O_IF:
            a = eval_cond();
            w = rw();
            if (!a) pc = w;
            break;
        case O_SETF: flag_set(rw()); break;
        case O_CLRF: flag_clr(rw()); break;
        case O_GIVE: item_give(rb()); sfx_play(8); break;
        case O_TAKE: item_take(rb()); break;
        case O_EV:
            a = rb();
            if (!ev_has(a)) {
                ev_give(a);
                infl_add(-2);
                sfx_play(11);
                dlg_say("CASEBOOK UPDATED.");
            }
            break;
        case O_INFL:
            a = rb();
            infl_add((int8_t)a);
            if ((int8_t)a > 0) { sfx_play(10); flash_red(3); }
            break;
        case O_ALERT: alert_add((int8_t)rb()); break;
        case O_ALERTSET: gs.alert = rb(); hud_dirty = 1; break;
        case O_CHOICE: op_choice(); break;
        case O_WARP:
            a = rb(); b = rb(); c = rb(); d = rb();
            dlg_close();
            warp_to(a, b, c, d);
            break;
        case O_MUSIC: a = rb(); if (a == 0xFF) music_stop(); else music_play(a); break;
        case O_MUSICRESUME: music_play(mh.music); break;
        case O_SFX: sfx_play(rb()); break;
        case O_WAIT: a = rb(); while (a--) cut_frame(); break;
        case O_FADEOUT: fade_out(); break;
        case O_FADEIN: fade_in(); break;
        case O_SHAKE: shake_t = rb(); break;
        case O_IMAGE: image_show(rb()); break;
        case O_IMAGE_END: image_show(0xFF); break;
        case O_AMOVE:
            a = rb(); b = rb(); c = rb();
            ac = find_actor(a);
            if (ac) {
                uint8_t i;
                ac->dir = b;
                for (i = 0; i < (uint8_t)(c * 16); i++) {
                    ac->x += ddx[b] * 16;
                    ac->y += ddy[b] * 16;
                    ac->anim++;
                    cut_frame();
                }
                ac->anim = 0;
            }
            break;
        case O_PMOVE: {
            uint8_t i;
            b = rb(); c = rb();
            pl_dir = b;
            for (i = 0; i < (uint8_t)(c * 16); i++) {
                pl_x += ddx[b] * 16;
                pl_y += ddy[b] * 16;
                pl_anim++;
                camera_update();
                cut_frame();
            }
            pl_anim = 0;
            break;
        }
        case O_PFACE: pl_dir = rb(); break;
        case O_SETTILE: a = rb(); b = rb(); c = rb(); map_set(a, b, c); break;
        case O_CHAPTER: chapter_card(rb()); break;
        case O_HEAL:
            a = rb();
            gs.hp = (gs.hp + a > gs.maxhp) ? gs.maxhp : gs.hp + a;
            hud_dirty = 1;
            break;
        case O_SAVE: save_prompt(); break;
        case O_ENDING: dlg_close(); ending_run(); goto done;
        case O_SPECIAL: special_call(rb()); break;
        case O_SETVAR: a = rb(); gs.vars[a] = rb(); break;
        case O_ADDVAR: a = rb(); gs.vars[a] += rb(); break;
        case O_AHIDE: ac = find_actor(rb()); if (ac) ac->type = ACT_NONE; break;
        case O_ASHOW: spawn_obj_actor(rb()); break;
        case O_NOISE: a = rb(); b = rb(); actors_noise(a * 16 + 8, b * 16 + 8, 80); break;
        case O_SHADOW:
            a = rb(); b = rb();
            if (a == 0xFF) big_shadow_on = 0;
            else {
                big_shadow_on = 1;
                big_shadow_x = a;
                big_shadow_y = b;
                sfx_play(10);
            }
            break;
        case O_AMMO: a = rb(); gs.ammo = gs.ammo + a > 24 ? 24 : gs.ammo + a; sfx_play(9); hud_dirty = 1; break;
        case O_BANDAGE: a = rb(); gs.bandages = gs.bandages + a > 9 ? 9 : gs.bandages + a; sfx_play(9); hud_dirty = 1; break;
        case O_BOTTLE: a = rb(); gs.bottles = gs.bottles + a > 9 ? 9 : gs.bottles + a; sfx_play(9); hud_dirty = 1; break;
        case O_UNLOCK: a = rb(); gs.music_unlock[a >> 3] |= 1 << (a & 7); break;
        case O_AFACE: a = rb(); b = rb(); ac = find_actor(a); if (ac) ac->dir = b; break;
        case O_FLASH: flash_white(4); break;
        case O_REDFLASH: flash_red(6); break;
        case O_CALL: w = rw(); run_one(w); break;
        case O_DAMAGE: player_damage(rb(), 0xFF); break;
        case O_REDRAW:
            fade_out();
            DISPLAY_OFF;
            map_load(cur_map);   /* reload base grid + patches (handles toggled flags) */
            render_sprites();
            DISPLAY_ON;
            fade_in();
            break;
        case O_WEAPON: gs.weapon = rb(); hud_dirty = 1; break;
        case O_CLOSE: dlg_close(); break;
        case O_PHIDE: shadow_mode = 0xFE; break;
        case O_PSHOW: shadow_mode = 0; break;
        case O_AWARP:
            a = rb(); b = rb(); c = rb();
            ac = find_actor(a);
            if (ac) { ac->x = (int16_t)b << 8; ac->y = (int16_t)c << 8; }
            break;
        case O_CREDITS: dlg_close(); credits_run(0); break;
        case O_CHECKPOINT: memcpy(&checkpoint, &gs, sizeof(gs)); break;
        default:
            goto done;
        }
        if (game_state != GS_PLAY) break;
    }
done:
    s_bank = sv_bank;
    s_base = sv_base;
    pc = sv_pc;
    (void)map_music;
}

void script_run(uint16_t id) {
    if (id == 0xFFFF || id >= NUM_SCRIPTS) return;
    run_one(id);
    dlg_close();
    hud_dirty = 1;
}

void script_queue(uint16_t id) {
    script_pending = id;
}
